function validateRoot(root) {
  if (typeof root !== 'string' || !root) throw Error('root must be a non-symlink directory');
  // lstat may follow a directory symlink when its spelling has a trailing slash.
  const parsed = path.parse(root);
  let target = root;
  while (target.length > parsed.root.length && /[\\/]$/.test(target)) target = target.slice(0, -1);
  const stat = fs.lstatSync(target);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}

function validateManifest(manifest) {
  if (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest)
    || manifest.version !== 1 || !Array.isArray(manifest.files)) throw Error('invalid manifest');

  const seen = new Set();
  for (const entry of manifest.files) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw Error('invalid manifest entry');
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest path');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)) throw Error('invalid sha256');
    if (!Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('invalid size');
    if (!Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid mode');
  }
}

export function verifyManifest(root, manifest) {
  validateManifest(manifest);
  validateRoot(root);

  const report = {ok:true,unchanged:[],changed:[],missing:[],unsafe:[]};
  const entries = [...manifest.files].sort((a, b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0);
  for (const expected of entries) {
    const current = inspect(root, expected.path);
    if (current.kind === 'missing') report.missing.push(expected.path);
    else if (current.kind === 'unsafe') report.unsafe.push(expected.path);
    else {
      const reasons = [];
      if (current.sha256 !== expected.sha256 || current.size !== expected.size) reasons.push('content');
      if (current.mode !== expected.mode) reasons.push('mode');
      if (reasons.length) report.changed.push({path:expected.path,reasons});
      else report.unchanged.push(expected.path);
    }
  }
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}

function runCli(argv) {
  const [command, ...args] = argv;
  if (command === 'create') {
    if (args.length < 1) throw Error('usage: snapshot.js create ROOT [PATH ...]');
    return {value:createManifest(args[0], args.slice(1)), exitCode:0};
  }
  if (command === 'verify') {
    if (args.length !== 2) throw Error('usage: snapshot.js verify ROOT MANIFEST_FILE');
    const manifest = JSON.parse(fs.readFileSync(args[1], 'utf8'));
    const value = verifyManifest(args[0], manifest);
    return {value, exitCode:value.ok ? 0 : 1};
  }
  throw Error('usage: snapshot.js create ROOT [PATH ...] | verify ROOT MANIFEST_FILE');
}

const invokedPath = process.argv[1] && path.resolve(process.argv[1]);
if (invokedPath === fileURLToPath(import.meta.url)) {
  try {
    const result = runCli(process.argv.slice(2));
    process.stdout.write(`${JSON.stringify(result.value)}\n`);
    process.exitCode = result.exitCode;
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

