import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createManifest, verifyManifest} from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
function temp(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-contract-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function put(root, name, data = name, mode = 0o640) {
  const full = path.join(root, ...name.split('/'));
  fs.mkdirSync(path.dirname(full), {recursive:true});
  fs.writeFileSync(full, data);
  fs.chmodSync(full, mode);
}
function entry(name, data = name, mode = 0o640) {
  const bytes = Buffer.from(data);
  return {path:name, sha256:hash(bytes), size:bytes.length, mode};
}
function cli(args) {
  return spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});
}

const invalidPaths = ['', '/absolute', 'a\\b', 'a\0b', 'a//b', './a', 'a/.', '../a', 'a/..', 'a/../b', 3, null];
test('canonical selections, empty selections, whitespace, Unicode, and JS ordering', t => {
  const root = temp(t);
  const names = ['é', 'a', 'Z', '😀', 'line\nbreak', 'tab\tname', 'space name'];
  for (const name of names) put(root, name);
  const before = [...names];
  const manifest = createManifest(root, names);
  assert.deepEqual(names, before);
  assert.deepEqual(manifest.files.map(x => x.path), [...names].sort((a,b) => a < b ? -1 : a > b ? 1 : 0));
  assert.deepEqual(createManifest(root, []), {version:1, files:[]});
  assert.deepEqual(verifyManifest(root, {version:1, files:[]}), {ok:true, unchanged:[], changed:[], missing:[], unsafe:[]});
  for (const selected of invalidPaths) assert.throws(() => createManifest(root, [selected]));
  assert.throws(() => createManifest(root, ['a', 'a']));
});

test('manifest validation is complete, strict, duplicate-aware, and non-mutating', t => {
  const root = temp(t);
  put(root, 'a', 'a');
  const good = entry('a', 'a');
  const invalid = [
    null, [], 1, {}, {version:2,files:[]}, {version:1,files:{}},
    {version:1,files:[null]}, {version:1,files:[[]]},
    {version:1,files:[{...good,path:''}]},
    {version:1,files:[good,{...good}]},
    {version:1,files:[{...good,sha256:'A'.repeat(64)}]},
    {version:1,files:[{...good,sha256:'0'.repeat(63)}]},
    {version:1,files:[{...good,size:-1}]},
    {version:1,files:[{...good,size:1.5}]},
    {version:1,files:[{...good,size:Number.MAX_SAFE_INTEGER + 1}]},
    {version:1,files:[{...good,mode:-1}]},
    {version:1,files:[{...good,mode:512}]},
    {version:1,files:[{...good,mode:1.5}]},
    {version:1,files:[good,{...good,path:'late',sha256:'bad'}]},
  ];
  for (const value of invalid) assert.throws(() => verifyManifest(root, value));

  const frozen = Object.freeze({version:1, ignored:true, files:Object.freeze([
    Object.freeze({...good, extra:'ignored'}),
  ])});
  assert.deepEqual(verifyManifest(root, frozen), {ok:true, unchanged:['a'], changed:[], missing:[], unsafe:[]});
  assert.equal(frozen.files[0].extra, 'ignored');
});

test('hash, byte size, and permission drift have exact ordered reasons', t => {
  const root = temp(t);
  put(root, 'both', 'abc', 0o640);
  put(root, 'hash-only', 'abc', 0o640);
  put(root, 'mode-only', 'abc', 0o640);
  put(root, 'size-only', 'abc', 0o640);
  const manifest = createManifest(root, ['size-only','mode-only','hash-only','both']);
  fs.writeFileSync(path.join(root, 'both'), 'longer'); fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.writeFileSync(path.join(root, 'hash-only'), 'xyz');
  fs.chmodSync(path.join(root, 'mode-only'), 0o600);
  fs.writeFileSync(path.join(root, 'size-only'), 'abcd');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false, unchanged:[],
    changed:[
      {path:'both', reasons:['content','mode']},
      {path:'hash-only', reasons:['content']},
      {path:'mode-only', reasons:['mode']},
      {path:'size-only', reasons:['content']},
    ], missing:[], unsafe:[],
  });
});

test('missing and unsafe are distinguished at intermediate and final components', t => {
  const root = temp(t);
  put(root, 'safe/file', 'ok');
  put(root, 'plain', 'not a directory');
  fs.mkdirSync(path.join(root, 'directory'));
  fs.symlinkSync(path.join(root, 'safe'), path.join(root, 'inside-link'));
  fs.symlinkSync(path.join(root, 'safe/file'), path.join(root, 'file-link'));
  const files = [
    entry('gone/file', 'x'), entry('safe/gone', 'x'), entry('plain/child', 'x'),
    entry('directory', 'x'), entry('inside-link/file', 'ok'), entry('file-link', 'ok'),
  ];
  const report = verifyManifest(root, {version:1,files});
  assert.deepEqual(report, {ok:false, unchanged:[], changed:[],
    missing:['gone/file','safe/gone'],
    unsafe:['directory','file-link','inside-link/file'],
  });
  assert.throws(() => createManifest(root, ['inside-link/file']));
});

test('roots reject files, missing paths, and symlinks including trailing slash', t => {
  const root = temp(t);
  put(root, 'file', 'x');
  fs.mkdirSync(path.join(root, 'real'));
  fs.symlinkSync(path.join(root, 'real'), path.join(root, 'link'));
  for (const bad of [path.join(root,'file'), path.join(root,'missing'), path.join(root,'link'), `${path.join(root,'link')}${path.sep}`]) {
    assert.throws(() => createManifest(bad, []));
    assert.throws(() => verifyManifest(bad, {version:1,files:[]}));
  }
});

test('APIs leave selections and selected files unchanged', t => {
  const root = temp(t);
  put(root, 'a', Buffer.from([0,1,2,255]), 0o604);
  const paths = Object.freeze(['a']);
  const before = fs.readFileSync(path.join(root,'a'));
  const manifest = createManifest(root, paths);
  const snapshot = JSON.stringify(manifest);
  assert.equal(verifyManifest(root, manifest).ok, true);
  assert.equal(JSON.stringify(manifest), snapshot);
  assert.deepEqual(fs.readFileSync(path.join(root,'a')), before);
  assert.equal(fs.statSync(path.join(root,'a')).mode & 0o777, 0o604);
});

test('CLI create and verify have exact success and drift semantics', t => {
  const root = temp(t);
  put(root, 'a', 'abc', 0o640);
  const created = cli(['create', root, 'a']);
  assert.equal(created.status, 0); assert.equal(created.stderr, '');
  assert.equal(created.stdout, `${JSON.stringify(createManifest(root,['a']))}\n`);
  const mf = path.join(root, 'manifest.json'); fs.writeFileSync(mf, created.stdout);
  const verified = cli(['verify', root, mf]);
  assert.equal(verified.status, 0); assert.equal(verified.stderr, '');
  assert.equal(verified.stdout, `${JSON.stringify(verifyManifest(root, JSON.parse(created.stdout)))}\n`);
  fs.writeFileSync(path.join(root,'a'), 'changed');
  const drift = cli(['verify', root, mf]);
  assert.equal(drift.status, 1); assert.equal(drift.stderr, '');
  assert.deepEqual(JSON.parse(drift.stdout).changed, [{path:'a',reasons:['content']}]);
});

test('CLI errors use exit 2, stderr only, and module import is silent', t => {
  const root = temp(t);
  const badJson = path.join(root, 'bad.json'); fs.writeFileSync(badJson, '{');
  const badManifest = path.join(root, 'manifest.json'); fs.writeFileSync(badManifest, '{"version":2,"files":[]}');
  for (const args of [[], ['bogus'], ['create'], ['verify',root], ['verify',root,badJson], ['verify',root,badManifest], ['verify',root,path.join(root,'absent')]]) {
    const result = cli(args);
    assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
  }
  const imported = spawnSync(process.execPath, ['--input-type=module','-e',`await import(${JSON.stringify(new URL('../snapshot.js', import.meta.url).href)})`], {encoding:'utf8'});
  assert.equal(imported.status, 0); assert.equal(imported.stdout, ''); assert.equal(imported.stderr, '');
});

