    if (current.kind === 'missing') report.missing.push(expected.path);
    else if (current.kind === 'unsafe') report.unsafe.push(expected.path);
    else {
      const reasons = [];
      if (current.sha256 !== expected.sha256 || current.size !== expected.size) reasons.push('content');
      if (current.mode !== expected.mode) reasons.push('mode');
      if (reasons.length) report.changed.push({path:expected.path,reasons});
      else report.unchanged.push(expected.path);
    }
  }
  report.ok = report.changed.length === 0 && report.missing.length === 0 && report.unsafe.length === 0;
  return report;
}

function runCli(argv) {
  const [command, ...args] = argv;
  if (command === 'create') {
    if (args.length < 1) throw Error('usage: snapshot.js create ROOT [PATH ...]');
    return {value:createManifest(args[0], args.slice(1)), exitCode:0};
  }
  if (command === 'verify') {
    if (args.length !== 2) throw Error('usage: snapshot.js verify ROOT MANIFEST_FILE');
    const manifest = JSON.parse(fs.readFileSync(args[1], 'utf8'));
    const value = verifyManifest(args[0], manifest);
    return {value, exitCode:value.ok ? 0 : 1};
  }
  throw Error('usage: snapshot.js create ROOT [PATH ...] | verify ROOT MANIFEST_FILE');
}

const invokedPath = process.argv[1] && path.resolve(process.argv[1]);
if (invokedPath === fileURLToPath(import.meta.url)) {
  try {
    const result = runCli(process.argv.slice(2));
    process.stdout.write(`${JSON.stringify(result.value)}\n`);
    process.exitCode = result.exitCode;
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

